package com.mad.edt.colleague.llm;

/**
 * A single message exchanged with a language model.
 */
public final class ChatMessage {

    /** Instruction that configures assistant behavior. */
    public static final String ROLE_SYSTEM = "system";
    /** Message authored by the end user. */
    public static final String ROLE_USER = "user";
    /** Message generated by the model. */
    public static final String ROLE_ASSISTANT = "assistant";

    private final String role;
    private final String content;

    private ChatMessage(final String theRole, final String theContent) {
        if(theRole == null || theRole.isEmpty()) {
            throw new IllegalArgumentException("message role is empty");
        }
        role = theRole;
        content = theContent == null ? "" : theContent;
    }

    /**
     * Creates a system message.
     *
     * @param theContent message text
     * @return the message
     */
    public static ChatMessage system(final String theContent) {
        return new ChatMessage(ROLE_SYSTEM, theContent);
    }

    /**
     * Creates a user message.
     *
     * @param theContent message text
     * @return the message
     */
    public static ChatMessage user(final String theContent) {
        return new ChatMessage(ROLE_USER, theContent);
    }

    /**
     * Creates an assistant message.
     *
     * @param theContent message text
     * @return the message
     */
    public static ChatMessage assistant(final String theContent) {
        return new ChatMessage(ROLE_ASSISTANT, theContent);
    }

    /**
     * @return the author role
     */
    public String getRole() {
        return role;
    }

    /**
     * @return the message text, never {@code null}
     */
    public String getContent() {
        return content;
    }

    @Override
    public String toString() {
        return role + ": " + content;
    }
}
